import{_ as l,a0 as d,w as g,s as p,I as n,x as o,a1 as a,A as i,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"如何在 Ubuntu 上安裝 MongoDB | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上安裝 MongoDB | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上安裝 MongoDB | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上安裝 MongoDB | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190304 How to Install MongoDB on Ubuntu","title":"如何在 Ubuntu 上安裝 MongoDB","tag":"201908","desc":""},"relativePath":"201908/20190304 How to Install MongoDB on Ubuntu.md","filePath":"[post].md"}'),r={name:"201908/20190304 How to Install MongoDB on Ubuntu.md"};function u(h,s,b,k,c,m){const t=d("Link");return g(),p("div",null,[s[25]||(s[25]=n("h1",{id:"如何在-ubuntu-上安裝-mongodb",tabindex:"-1"},[o("如何在 Ubuntu 上安裝 MongoDB "),n("a",{class:"header-anchor",href:"#如何在-ubuntu-上安裝-mongodb","aria-label":"Permalink to “如何在 Ubuntu 上安裝 MongoDB”"},"​")],-1)),s[26]||(s[26]=n("blockquote",null,[n("p",null,"本教程介紹了在 Ubuntu 和基於 Ubuntu 的 Linux 發行版上安裝 MongoDB 的兩種方法。")],-1)),n("p",null,[a(t,{href:"https://www.mongodb.com/"},{default:i(()=>[...s[0]||(s[0]=[o("MongoDB",-1)])]),_:1}),s[1]||(s[1]=o(" 是一個越來越流行的自由開源的 NoSQL 資料庫，它將數據存儲在類似 JSON 的靈活文檔集中，這與 SQL 資料庫中常見的表格形式形成對比。",-1))]),s[27]||(s[27]=e(`<p>你很可能發現在現代 Web 應用中使用 MongoDB。它的文檔模型使得使用各種編程語言能非常直觀地訪問和處理它。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/mongodb-ubuntu.jpeg?resize=800%2C450&amp;ssl=1" alt="mongodb Ubuntu"></p><p>在本文中，我將介紹兩種在 Ubuntu 上安裝 MongoDB 的方法。</p><h3 id="在基於-ubuntu-的發行版上安裝-mongodb" tabindex="-1">在基於 Ubuntu 的發行版上安裝 MongoDB <a class="header-anchor" href="#在基於-ubuntu-的發行版上安裝-mongodb" aria-label="Permalink to “在基於 Ubuntu 的發行版上安裝 MongoDB”">​</a></h3><ol><li>使用 Ubuntu 倉庫安裝 MongoDB。簡單但不是最新版本的 MongoDB</li><li>使用其官方倉庫安裝 MongoDB。稍微複雜，但你能得到最新版本的 MongoDB。</li></ol><p>第一種安裝方法更容易，但如果你計劃使用官方支持的最新版本，那麼我建議使用第二種方法。</p><p>有些人可能更喜歡使用 snap 包。Ubuntu 軟件中心提供了 snap，但我不建議使用它們，因為他們現在已經過期了，因此我這裏不會提到。</p><h3 id="方法-1-從-ubuntu-倉庫安裝-mongodb" tabindex="-1">方法 1：從 Ubuntu 倉庫安裝 MongoDB <a class="header-anchor" href="#方法-1-從-ubuntu-倉庫安裝-mongodb" aria-label="Permalink to “方法 1：從 Ubuntu 倉庫安裝 MongoDB”">​</a></h3><p>這是在系統中安裝 MongoDB 的簡便方法，你只需輸入一個命令即可。</p><h4 id="安裝-mongodb" tabindex="-1">安裝 MongoDB <a class="header-anchor" href="#安裝-mongodb" aria-label="Permalink to “安裝 MongoDB”">​</a></h4><p>首先，確保你的包是最新的。打開終端並輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt upgrade -y</span></span></code></pre></div><p>繼續安裝 MongoDB：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install mongodb</span></span></code></pre></div><p>這就完成了！MongoDB 現在安裝到你的計算機上了。</p><p>MongoDB 服務應該在安裝時自動啓動，但要檢查服務狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl status mongodb</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/02/mongodb_check_status.jpg?fit=800%2C574&amp;ssl=1" alt="Check if the MongoDB service is running."></p><p>你可以看到該服務是<strong>活動</strong>的。</p><h4 id="運行-mongodb" tabindex="-1">運行 MongoDB <a class="header-anchor" href="#運行-mongodb" aria-label="Permalink to “運行 MongoDB”">​</a></h4><p>MongoDB 目前是一個 systemd 服務，因此我們使用 <code>systemctl</code> 來檢查和修改它的狀態，使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl status mongodb</span></span>
<span class="line"><span>sudo systemctl stop mongodb</span></span>
<span class="line"><span>sudo systemctl start mongodb</span></span>
<span class="line"><span>sudo systemctl restart mongodb</span></span></code></pre></div><p>你也可以修改 MongoDB 是否自動隨系統啓動（默認：啓用）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl disable mongodb</span></span>
<span class="line"><span>sudo systemctl enable mongodb</span></span></code></pre></div><p>要開始使用（創建和編輯）資料庫，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mongo</span></span></code></pre></div>`,26)),n("p",null,[s[3]||(s[3]=o("這將啓動 ",-1)),s[4]||(s[4]=n("strong",null,"mongo shell",-1)),s[5]||(s[5]=o("。有關查詢和選項的詳細信息，請查看",-1)),a(t,{href:"https://docs.mongodb.com/manual/tutorial/getting-started/"},{default:i(()=>[...s[2]||(s[2]=[o("手冊",-1)])]),_:1}),s[6]||(s[6]=o("。",-1))]),s[28]||(s[28]=e(`<p><strong>注意：</strong>根據你計劃使用 MongoDB 的方式，你可能需要調整防火牆。不過這超出了本篇的內容，並且取決於你的配置。</p><h4 id="卸載-mongodb" tabindex="-1">卸載 MongoDB <a class="header-anchor" href="#卸載-mongodb" aria-label="Permalink to “卸載 MongoDB”">​</a></h4><p>如果你從 Ubuntu 倉庫安裝 MongoDB 並想要卸載它（可能要使用官方支持的方式安裝），請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl stop mongodb</span></span>
<span class="line"><span>sudo apt purge mongodb</span></span>
<span class="line"><span>sudo apt autoremove</span></span></code></pre></div><p>這應該會完全卸載 MongoDB。確保<strong>備份</strong>你可能想要保留的任何集合或文檔，因為它們將被刪除！</p><h3 id="方法-2-在-ubuntu-上安裝-mongodb-社區版" tabindex="-1">方法 2：在 Ubuntu 上安裝 MongoDB 社區版 <a class="header-anchor" href="#方法-2-在-ubuntu-上安裝-mongodb-社區版" aria-label="Permalink to “方法 2：在 Ubuntu 上安裝 MongoDB 社區版”">​</a></h3><p>這是推薦的安裝 MongoDB 的方法，它使用包管理器。你需要多打幾條命令，對於 Linux 新手而言，這可能會感到害怕。</p><p>但沒有什麼可怕的！我們將一步步説明安裝過程。</p><h4 id="安裝-mongodb-1" tabindex="-1">安裝 MongoDB <a class="header-anchor" href="#安裝-mongodb-1" aria-label="Permalink to “安裝 MongoDB”">​</a></h4><p>由 MongoDB Inc. 維護的包稱為 <code>mongodb-org</code>，而不是 <code>mongodb</code>（這是 Ubuntu 倉庫中包的名稱）。在開始之前，請確保系統上未安裝 <code>mongodb</code>。因為包之間會發生衝突。讓我們開始吧！</p><p>首先，我們必須導入公鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-key adv --keyserver hkp://keyserver.ubuntu.com:80 --recv 9DA31620334BD75D9DCB49F368818C72E52529D4</span></span></code></pre></div><p>現在，你需要在源列表中添加一個新的倉庫，以便你可以安裝 MongoDB 社區版並獲得自動更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;deb [ arch=amd64 ] https://repo.mongodb.org/apt/ubuntu $(lsb_release -cs)/mongodb-org/4.0 multiverse&quot; | sudo tee /etc/apt/sources.list.d/mongodb-org-4.0.list</span></span></code></pre></div><p>要安裝 <code>mongodb-org</code>，我們需要更新我們的包資料庫，以便系統知道可用的新包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>現在你可以安裝<strong>最新穩定版</strong>的 MongoDB：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install -y mongodb-org</span></span></code></pre></div><p>或者某個<strong>特定版本</strong>（在 <code>=</code> 後面修改版本號）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install -y mongodb-org=4.0.6 mongodb-org-server=4.0.6 mongodb-org-shell=4.0.6 mongodb-org-mongos=4.0.6 mongodb-org-tools=4.0.6</span></span></code></pre></div><p>如果你選擇安裝特定版本，請確保在所有位置都修改了版本號。如果你修改了 <code>mongodb-org=4.0.6</code>，你將安裝最新版本。</p><p>默認情況下，使用包管理器（<code>apt-get</code>）更新時，MongoDB 將更新為最新的版本。要阻止這種情況發生（並凍結為已安裝的版本），請使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;mongodb-org hold&quot; | sudo dpkg --set-selections</span></span>
<span class="line"><span>echo &quot;mongodb-org-server hold&quot; | sudo dpkg --set-selections</span></span>
<span class="line"><span>echo &quot;mongodb-org-shell hold&quot; | sudo dpkg --set-selections</span></span>
<span class="line"><span>echo &quot;mongodb-org-mongos hold&quot; | sudo dpkg --set-selections</span></span>
<span class="line"><span>echo &quot;mongodb-org-tools hold&quot; | sudo dpkg --set-selections</span></span></code></pre></div><p>你現在已經成功安裝了 MongoDB！</p><h4 id="配置-mongodb" tabindex="-1">配置 MongoDB <a class="header-anchor" href="#配置-mongodb" aria-label="Permalink to “配置 MongoDB”">​</a></h4><p>默認情況下，包管理器將創建 <code>/var/lib/mongodb</code> 和 <code>/var/log/mongodb</code>，MongoDB 將使用 <code>mongodb</code> 用户帳户運行。</p>`,26)),n("p",null,[s[8]||(s[8]=o("我不會去更改這些默認設置，因為這超出了本指南的範圍。有關詳細信息，請查看",-1)),a(t,{href:"https://docs.mongodb.com/manual/"},{default:i(()=>[...s[7]||(s[7]=[o("手冊",-1)])]),_:1}),s[9]||(s[9]=o("。",-1))]),s[29]||(s[29]=e(`<p><code>/etc/mongod.conf</code> 中的設置在啓動/重新啓動 <strong>mongodb</strong> 服務實例時生效。</p><h5 id="運行-mongodb-1" tabindex="-1">運行 MongoDB <a class="header-anchor" href="#運行-mongodb-1" aria-label="Permalink to “運行 MongoDB”">​</a></h5><p>要啓動 mongodb 的守護進程 <code>mongod</code>，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo service mongod start</span></span></code></pre></div><p>現在你應該驗證 <code>mongod</code> 進程是否已成功啓動。此信息（默認情況下）保存在 <code>/var/log/mongodb/mongod.log</code> 中。我們來看看文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cat /var/log/mongodb/mongod.log</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/02/mongodb_org_check_logs.jpg?fit=800%2C467&amp;ssl=1" alt="Check MongoDB logs to see if the process is running properly."></p><p>只要你在某處看到：<code>[initandlisten] waiting for connections on port 27017</code>，就説明進程正常運行。</p><p><strong>注意</strong>：27017 是 <code>mongod</code> 的默認端口。</p><p>要停止/重啓 <code>mongod</code>，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo service mongod stop</span></span>
<span class="line"><span>sudo service mongod restart</span></span></code></pre></div><p>現在，你可以通過打開 <strong>mongo shell</strong> 來使用 MongoDB：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mongo</span></span></code></pre></div><h4 id="卸載-mongodb-1" tabindex="-1">卸載 MongoDB <a class="header-anchor" href="#卸載-mongodb-1" aria-label="Permalink to “卸載 MongoDB”">​</a></h4><p>運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo service mongod stop</span></span>
<span class="line"><span>sudo apt purge mongodb-org*</span></span></code></pre></div><p>要刪除<strong>資料庫</strong>和<strong>日誌文件</strong>（確保<strong>備份</strong>你要保留的內容！）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rm -r /var/log/mongodb</span></span>
<span class="line"><span>sudo rm -r /var/lib/mongodb</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>MongoDB 是一個很棒的 NoSQL 資料庫，它易於集成到現代項目中。我希望本教程能幫助你在 Ubuntu 上安裝它！在下面的評論中告訴我們你計劃如何使用 MongoDB。</p><hr>`,21)),n("p",null,[s[11]||(s[11]=o("via: ",-1)),a(t,{href:"https://itsfoss.com/install-mongodb-ubuntu"},{default:i(()=>[...s[10]||(s[10]=[o("https://itsfoss.com/install-mongodb-ubuntu",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=o("作者：",-1)),a(t,{href:"https://itsfoss.com/author/sergiu/"},{default:i(()=>[...s[12]||(s[12]=[o("Sergiu",-1)])]),_:1}),s[17]||(s[17]=o(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[13]||(s[13]=[o("lujun9972",-1)])]),_:1}),s[18]||(s[18]=o(" 譯者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:i(()=>[...s[14]||(s[14]=[o("geekpi",-1)])]),_:1}),s[19]||(s[19]=o(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[15]||(s[15]=[o("wxy",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=o("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[20]||(s[20]=[o("LCTT",-1)])]),_:1}),s[23]||(s[23]=o(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...s[21]||(s[21]=[o("Linux中國",-1)])]),_:1}),s[24]||(s[24]=o(" 榮譽推出",-1))])])}const B=l(r,[["render",u]]);export{D as __pageData,B as default};
